/* @lc app=leetcode id=2170 lang=kotlin */
class Solution { fun minimumOperations(nums: IntArray): Int = nums.filterIndexed { i, _ -> i % 2 == 0 }.groupingBy { it }.eachCount().toList().sortedByDescending { it.second }.let { es -> nums.filterIndexed { i, _ -> i % 2 != 0 }.groupingBy { it }.eachCount().toList().sortedByDescending { it.second }.let { os -> if ((es.getOrNull(0)?.first ?: -1) != (os.getOrNull(0)?.first ?: -2)) nums.size - (es.getOrNull(0)?.second ?: 0) - (os.getOrNull(0)?.second ?: 0) else minOf(nums.size - (es.getOrNull(0)?.second ?: 0) - (os.getOrNull(1)?.second ?: 0), nums.size - (es.getOrNull(1)?.second ?: 0) - (os.getOrNull(0)?.second ?: 0)) } } }